const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry: Tshopo province in DRC
  var tshopo = ee.FeatureCollection("FAO/GAUL_SIMPLIFIED_500m/2015/level1")
    .filter(ee.Filter.eq('ADM0_NAME', 'Democratic Republic of the Congo'))
    .filter(ee.Filter.eq('ADM1_NAME', 'Tshopo'));

  // Check if geometry exists
  var tshopoSize = tshopo.size().getInfo();
  if (tshopoSize === 0) {
    // Fallback: use Kisangani point with 100km buffer
    print("No province boundary found, using Kisangani buffer.");
    tshopo = ee.Geometry.Point([25.1910, 0.5153]).buffer(100000); // 100km buffer
  } else {
    tshopo = tshopo.geometry();
  }

  // 2. Load Hansen Global Forest Change dataset
  var hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_10');

  // Create loss mask (2001-2023): lossyear 1=2001, 23=2023
  var lossMask = hansen.select('lossyear').gte(1).and(hansen.select('lossyear').lte(23));

  // 3. Calculate loss area in sq km
  // Each pixel area in sq meters, convert to sq km (1e6 m² = 1 km²)
  var lossArea = ee.Image.pixelArea()
    .multiply(lossMask)
    .divide(1e6); // Convert to km²

  // 4. Reduce region to sum loss area
  var lossStats = lossArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: tshopo,
    scale: 3000, // Using 3km scale for performance
    maxPixels: 1e12,
    bestEffort: true
  });

  var totalLoss = lossStats.get('area');
  var totalLossValue = totalLoss.getInfo();

  // 5. Validate and output
  if (totalLossValue === null || totalLossValue === undefined) {
    print("Calculation returned null/undefined.");
    print("<answer>C3</answer>");
  } else if (isNaN(totalLossValue)) {
    print("Calculation resulted in NaN.");
    print("<answer>C3</answer>");
  } else {
    // Check if totalLossValue is reasonable (not negative or extremely large)
    if (totalLossValue < 0 || totalLossValue > 1e7) { // > 10M sq km unlikely
      print("Loss area out of valid range:", totalLossValue);
      print("<answer>C3</answer>");
    } else {
      print("Total forest loss since 2001 (sq km):", totalLossValue);
      if (totalLossValue < 15000) {
        print("<answer>A</answer>");
      } else {
        print("<answer>B</answer>");
      }
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
